svg.script:
(() => {
    const frame = document.getElementById('site');
    const page = "<!DOCTYPE html>
<html lang="en">
<head>
<base id="svg-base">
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="color-scheme" content="dark">
<title>Geeks Bunker</title>
<link id="favicon-link" rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='12' fill='%238edb44'/%3E%3Ctext x='32' y='43' text-anchor='middle' font-size='36' font-family='Arial' font-weight='bold'%3EG%3C/text%3E%3C/svg%3E">
<style>
:root { color-scheme:dark; --accent:#8edb44; --ink:#f5f6f7; --muted:#bbc0c8; --surface:rgba(23,27,33,.94); --line:rgba(255,255,255,.13); --wallpaper:none; }
* { box-sizing:border-box; }
html { min-height:100%; background:#101318; }
body { margin:0; min-height:100svh; color:var(--ink); font:15px/1.5 "Segoe UI",Inter,Arial,sans-serif; -webkit-font-smoothing:antialiased; }
button,input,select { font:inherit; } button,a,input,select { -webkit-tap-highlight-color:transparent; }
button { color:inherit; cursor:pointer; } a { color:inherit; text-decoration:none; } button { border:0; }
button:disabled { opacity:.45; cursor:not-allowed; } .hidden { display:none!important; }
:focus-visible { outline:3px solid var(--accent); outline-offset:4px; }
.wallpaper,.wallpaper-shade { position:fixed; inset:0; z-index:-2; pointer-events:none; }
.wallpaper { background-image:var(--wallpaper); background-size:cover; background-position:center; background-color:#101318; }
.wallpaper-shade { background:rgba(4,7,13,.34); z-index:-1; }
.topbar { min-height:100px; max-width:1600px; margin:auto; padding:28px 5%; display:flex; align-items:center; gap:38px; }
.brand { display:flex; align-items:center; gap:12px; font-weight:650; font-size:17px; letter-spacing:-.5px; white-space:nowrap; }
.brand-mark { display:inline-flex; position:relative; align-items:center; justify-content:center; width:36px; height:36px; border-radius:9px; color:#101b0c; background:var(--accent); font-size:25px; font-weight:800; letter-spacing:-3px; padding-right:4px; flex-shrink:0; }
.brand-mark span { font-size:20px; position:absolute; right:5px; bottom:-2px; }
.topbar nav { display:flex; align-items:center; gap:28px; }.nav-item { padding:8px 0; position:relative; background:none; font-weight:550; color:#b9bdc4; white-space:nowrap; }.nav-item:hover { color:white; }.nav-item.active { color:#fff; }.nav-item.active:after { content:''; position:absolute; bottom:0; height:3px; background:var(--accent); left:0; right:0; }
.header-tools { margin-left:auto; display:flex; align-items:center; gap:22px; }#dashboard-clock { font-variant-numeric:tabular-nums; color:#d7dbe1; white-space:nowrap; font-size:13px; }.profile-button { display:flex; align-items:center; gap:9px; background:none; padding:0; font-size:13px; }.avatar { width:32px; height:32px; display:grid; place-items:center; background:#dde4ec; color:#19232a; font-size:14px; font-weight:700; border-radius:50%; }
main { max-width:1600px; margin:0 auto; padding:0 5%; min-height:calc(100svh - 170px); }.page { padding:28px 0 44px; }.home-page { padding-top:58px; }.eyebrow { font-size:10px; font-weight:700; letter-spacing:2px; margin:0 0 12px; color:#d7dce2; }h1 { font-size:clamp(30px,3.4vw,48px); font-weight:450; line-height:1.15; letter-spacing:-1.8px; margin:0 0 15px; }h2 { font-size:18px; font-weight:550; margin:0; letter-spacing:-.3px; }.welcome>p:last-child { color:#c6cbd3; font-size:16px; margin:0; }.welcome { margin-bottom:52px; }.section-heading { display:flex; align-items:center; justify-content:space-between; gap:16px; margin-bottom:16px; }.text-button { color:#e7e9ec; background:none; padding:5px 0; text-align:left; font-size:13px; }.text-button:hover { color:var(--accent); }.muted { color:var(--muted); }.small { font-size:12px; }
.home-strip { display:grid; grid-template-columns:1.24fr 4fr; gap:14px; }.library-tile { min-height:222px; position:relative; display:flex; flex-direction:column; justify-content:space-between; align-items:flex-start; padding:22px; border-radius:7px; background:var(--accent); color:#15210d; text-align:left; transition:transform .16s; }.library-tile strong { font-size:21px; font-weight:650; letter-spacing:-.6px; }.library-tile small { display:block; margin-top:4px; opacity:.75; font-size:12px; }.tile-symbol { font-size:43px; line-height:1; }.tile-arrow { position:absolute; top:18px; right:20px; font-size:23px; }.library-tile:hover { transform:translateY(-3px); }.featured-games { min-width:0; display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:14px; }.featured-card { padding:0; position:relative; overflow:hidden; border-radius:7px; background:#202830; height:100%; min-height:222px; min-width:0; text-align:left; transition:transform .16s; }.featured-card img { width:100%; height:100%; object-fit:cover; }.featured-card .featured-caption { position:absolute; left:0; right:0; bottom:0; padding:13px 12px; background:rgba(12,16,21,.88); font-size:13px; font-weight:550; }.featured-card:hover { transform:translateY(-3px); }.game-placeholder { grid-column:1/-1; display:grid; place-items:center; color:var(--muted); background:var(--surface); border:1px solid var(--line); border-radius:7px; min-height:222px; }
.shortcuts-heading { margin-top:34px; }.shortcuts-heading .muted { font-size:12px; }.shortcut-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:14px; }.shortcut { display:flex; align-items:center; gap:15px; min-width:0; padding:21px 18px; border-radius:6px; border:1px solid var(--line); background:var(--surface); text-align:left; transition:border-color .16s; }.shortcut:hover { border-color:var(--accent); }.shortcut-icon { font-size:26px; line-height:1; color:var(--accent); }.shortcut strong { display:block; font-size:14px; font-weight:550; }.shortcut small { display:block; color:var(--muted); font-size:11px; margin-top:3px; }.shortcut-arrow { margin-left:auto; color:#8a949f; }
.dashboard-footer { max-width:1600px; margin:auto; display:flex; flex-wrap:wrap; justify-content:space-between; gap:12px; padding:18px 5% 24px; color:#9ba6b3; font-size:10px; letter-spacing:1px; }.dashboard-footer>div { display:flex; gap:22px; letter-spacing:0; }.dashboard-footer button { padding:0; background:none; color:inherit; font-size:10px; }.footer-dot { margin:0 7px; }.dashboard-footer a:hover,.dashboard-footer button:hover { color:white; }
.page-heading { display:flex; align-items:flex-end; justify-content:space-between; gap:24px; margin:10px 0 30px; }.page-heading h1 { margin-bottom:0; }.provider-tabs { display:flex; align-items:center; gap:6px; padding:5px; border:1px solid var(--line); border-radius:7px; background:rgba(15,20,27,.9); }.provider-tabs button { background:none; padding:10px 22px; border-radius:4px; color:#b9c2cc; font-size:13px; }.provider-tabs button[aria-selected=true] { background:var(--accent); color:#12200b; font-weight:650; }
.library-controls { display:flex; align-items:center; justify-content:space-between; gap:20px; margin-bottom:24px; }.search-field { display:flex; align-items:center; gap:12px; border:1px solid var(--line); border-radius:5px; padding:0 15px; background:var(--surface); width:min(430px,100%); }.search-field>span { color:#a8b3c1; font-size:25px; }.search-field input { border:0; background:none; padding:12px 0; width:100%; min-width:0; outline:none; }.search-field:focus-within { border-color:var(--accent); }#g8me-catalog-status { color:var(--muted); font-size:12px; text-align:right; }.game-grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(152px,1fr)); gap:20px; }.gn-game-card { background:none; border:0; text-align:left; padding:0; min-width:0; }.gn-game-art { display:grid; place-items:center; position:relative; width:100%; aspect-ratio:1; border-radius:7px; overflow:hidden; color:#a1b1c2; background:#242e3b; border:1px solid var(--line); transition:transform .15s; }.gn-game-art img { position:absolute; inset:0; width:100%; height:100%; object-fit:cover; }.gn-game-card:hover .gn-game-art { transform:translateY(-3px); outline:2px solid var(--accent); outline-offset:2px; }.gn-game-name { display:block; padding:10px 1px 2px; font-size:13px; line-height:1.3; overflow-wrap:anywhere; }.gn-empty { grid-column:1/-1; padding:50px 0; color:var(--muted); }
.button { display:inline-flex; align-items:center; justify-content:center; gap:8px; padding:11px 19px; min-height:42px; border:1px solid rgba(255,255,255,.17); border-radius:5px; background:#2c3440; color:#f4f5f7; font-size:13px; font-weight:550; }.button:hover { background:#3d4755; }.button.primary { background:var(--accent); border-color:var(--accent); color:#13200a; }.button.primary:hover { filter:brightness(1.08); }.button.quiet { background:transparent; border-color:transparent; color:var(--muted); }.more-button { display:flex; margin:30px auto 0; min-width:220px; }.panel { background:var(--surface); border:1px solid var(--line); border-radius:7px; padding:26px; }.panel h2 { margin-bottom:14px; }.panel p { line-height:1.7; }input,select { color:#f3f5f7; border:1px solid #475363; border-radius:4px; padding:11px 12px; background:#1a222c; width:100%; min-width:0; }input::placeholder { color:#8f9eae; }label { display:block; font-size:12px; color:#c9d0d9; }label>input,label>select { display:block; margin:8px 0 18px; font-size:14px; }.settings-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:20px; max-width:1040px; }.setting-row { display:flex; align-items:center; justify-content:space-between; padding-top:22px; gap:16px; font-size:14px; }.setting-row input { width:18px; height:18px; margin:0; accent-color:var(--accent); }.links-layout { display:grid; grid-template-columns:310px 1fr; gap:30px; margin-bottom:34px; }.subheading { margin:0 0 16px; }.saved-links,.website-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:10px; }.website-grid { grid-template-columns:repeat(4,minmax(0,1fr)); margin-top:20px; }.website-link,.saved-link { display:flex; align-items:center; justify-content:space-between; gap:8px; background:var(--surface); padding:15px; border-radius:5px; border:1px solid var(--line); min-width:0; text-align:left; color:#e8edf2; font-size:13px; }.website-link:hover,.saved-link:hover { border-color:var(--accent); }.saved-link a { overflow-wrap:anywhere; }.delete-link { background:none; padding:4px; color:#e6a2a2; font-size:18px; }.credits-panel { max-width:700px; }dl { display:grid; grid-template-columns:150px 1fr; gap:15px; margin:25px 0; }dt { color:var(--muted); }dd { margin:0; }
.setup-dialog { width:min(850px,calc(100% - 36px)); max-height:calc(100svh - 36px); margin:auto; padding:34px 38px; background:#171d26; color:#f4f6f8; border:1px solid #3b4655; border-radius:12px; box-shadow:0 25px 100px #0008; }.setup-dialog::backdrop { background:rgba(5,9,16,.7); backdrop-filter:blur(12px); }.setup-heading { display:flex; align-items:center; gap:12px; margin-bottom:22px; }.setup-heading .eyebrow { margin:0; }.setup-dialog h1 { font-size:34px; letter-spacing:-1px; margin-bottom:8px; }.setup-description { font-size:13px; margin:0 0 26px; }.setup-fields { display:grid; grid-template-columns:1fr 1fr; gap:35px; }fieldset { border:0; margin:0 0 22px; padding:0; min-width:0; }legend { padding:0; margin-bottom:12px; font-size:12px; color:#c9d0d9; }.accent-choices { display:flex; gap:12px; margin-top:3px; flex-wrap:wrap; }.accent-choice { width:30px; height:30px; border-radius:50%; background:var(--choice); border:3px solid transparent; box-shadow:inset 0 0 0 2px #171d26; }.accent-choice[aria-pressed=true] { outline:2px solid white; outline-offset:2px; }.wallpaper-choices { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:14px; }.wallpaper-choice { padding:0; border:2px solid transparent; border-radius:6px; background:#222c38; text-align:left; overflow:hidden; }.wallpaper-choice img { width:100%; aspect-ratio:1.75; object-fit:cover; display:block; }.wallpaper-choice span { display:block; padding:9px 10px; color:#c7d0da; font-size:12px; }.wallpaper-choice[aria-pressed=true] { border-color:var(--accent); }.wallpaper-choice[aria-pressed=true] span { color:var(--accent); }.setup-bottom { border-top:1px solid var(--line); display:flex; align-items:center; justify-content:space-between; gap:20px; padding-top:20px; }.setup-bottom>div { display:flex; gap:8px; }.setup-bottom p { margin:0; }
#gn-game-player { position:fixed; inset:0; z-index:100; background:#10151c; display:flex; flex-direction:column; }.gn-player-toolbar { display:flex; align-items:center; gap:10px; padding:10px 16px; background:#1b222c; border-bottom:1px solid var(--line); }.gn-player-toolbar h2 { flex:1; min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; font-size:15px; }.gn-player-toolbar .button { min-height:36px; padding:8px 14px; font-size:12px; }#gn-game-player:fullscreen .gn-player-toolbar { display:none; }.gn-player-stage { flex:1; min-height:0; position:relative; }#gn-frame-host { height:100%; width:100%; }#gn-frame-host iframe { display:block; height:100%; width:100%; border:0; background:#10151c; }.gn-player-message { position:absolute; inset:0; display:flex; align-items:center; justify-content:center; flex-direction:column; gap:15px; padding:30px; background:#10151c; text-align:center; }body:has(#gn-game-player:not(.hidden)) { overflow:hidden; }.toast { position:fixed; bottom:24px; left:50%; transform:translateX(-50%); background:#2d3b4c; color:white; padding:12px 22px; border:1px solid #5c6b7e; border-radius:6px; z-index:200; max-width:calc(100% - 32px); font-size:13px; }
@media (min-width:1500px) { .home-page { padding-top:85px; }.welcome { margin-bottom:70px; }.library-tile { min-height:260px; } }
@media (max-width:1050px) { .topbar { gap:25px; }.brand>span:last-child { display:none; }.topbar nav { gap:22px; }.header-tools { gap:14px; }.profile-button>span:last-child { display:none; }.home-strip { grid-template-columns:1.1fr 3fr; }.featured-games { grid-template-columns:repeat(3,minmax(0,1fr)); }.featured-card:nth-child(4) { display:none; }.shortcut-grid { gap:10px; }.shortcut { padding:18px 12px; gap:10px; }.shortcut small { font-size:10px; }.website-grid { grid-template-columns:repeat(3,minmax(0,1fr)); }.saved-links { grid-template-columns:repeat(2,minmax(0,1fr)); } }
@media (max-width:650px) { .topbar { flex-wrap:wrap; min-height:100px; padding:20px 5% 8px; gap:18px; }.brand>span:last-child { display:block; font-size:15px; }.header-tools { margin-left:auto; }#dashboard-clock { font-size:11px; }.topbar nav { order:3; width:100%; justify-content:space-between; gap:12px; }.nav-item { font-size:12px; }.home-page { padding-top:34px; }.welcome { margin-bottom:30px; }.welcome>p:last-child { font-size:13px; max-width:270px; }h1 { font-size:33px; letter-spacing:-1px; }.eyebrow { font-size:9px; }h2 { font-size:16px; }.text-button { font-size:11px; }.home-strip { display:flex; flex-direction:column; gap:14px; }.library-tile { min-height:125px; padding:18px; flex-direction:row; align-items:center; justify-content:flex-start; gap:20px; }.library-tile strong { font-size:20px; }.tile-symbol { font-size:38px; }.tile-arrow { top:14px; right:15px; font-size:20px; }.featured-games { grid-template-columns:repeat(3,minmax(0,1fr)); gap:10px; }.featured-caption { padding:9px!important; font-size:11px!important; }.shortcuts-heading .muted { display:none; }.shortcut-grid { grid-template-columns:1fr; }.shortcut { padding:17px; }.shortcut small { font-size:11px; }.dashboard-footer { font-size:8px; padding-top:8px; }.dashboard-footer>div { gap:16px; }.page-heading { align-items:flex-start; flex-direction:column; gap:20px; }.provider-tabs { width:100%; }.provider-tabs button { flex:1; }.library-controls { flex-direction:column; gap:8px; align-items:stretch; }.search-field { width:100%; }#g8me-catalog-status { text-align:left; margin:4px 0 12px; }.game-grid { grid-template-columns:repeat(2,minmax(0,1fr)); gap:20px 14px; }.gn-game-name { font-size:12px; }.settings-grid,.links-layout { grid-template-columns:1fr; gap:18px; }.saved-links,.website-grid { grid-template-columns:repeat(2,minmax(0,1fr)); }.panel { padding:22px; }.setup-dialog { padding:24px 22px; border-radius:9px; }.setup-dialog h1 { font-size:27px; }.setup-fields { grid-template-columns:1fr; gap:0; }.setup-fields label>input { margin-bottom:22px; }.accent-choices { gap:15px; }.wallpaper-choices { gap:8px; }.wallpaper-choice img { aspect-ratio:1.3; }.wallpaper-choice span { padding:8px 6px; font-size:10px; }.setup-bottom { flex-direction:column; align-items:stretch; gap:16px; }.setup-bottom>div { justify-content:flex-end; }.gn-player-toolbar { flex-wrap:wrap; padding:9px; gap:7px; }.gn-player-toolbar h2 { flex-basis:100%; }.gn-player-toolbar .button { flex:1; padding:8px; font-size:11px; }dl { grid-template-columns:1fr; gap:6px; }dd { margin-bottom:12px; } }
@media (prefers-reduced-motion:reduce) { *,*:before,*:after { scroll-behavior:auto!important; transition:none!important; animation:none!important; } }body.reduce-motion *,body.reduce-motion *:before { transition:none!important; animation:none!important; }

@media(max-width:650px){.featured-card{height:auto;min-height:150px;aspect-ratio:.78;}}
@media(max-width:650px){.featured-card{aspect-ratio:auto;height:150px;min-height:150px;}}
@media(max-height:800px) and (min-width:651px){.topbar{min-height:76px;padding-top:18px;padding-bottom:18px}.home-page{padding-top:20px}.welcome{margin-bottom:26px}.welcome h1{font-size:38px}.library-tile,.featured-card{min-height:180px}.shortcuts-heading{margin-top:25px}.shortcut{padding-top:17px;padding-bottom:17px}.page{padding-bottom:22px}.dashboard-footer{padding-top:12px;padding-bottom:16px}main{min-height:calc(100svh - 136px)}}

/* Dark Liquid Glass: shared material, with opaque fallbacks for older browsers. */
:root {
    --surface: rgba(18, 22, 30, .10);
    --line: rgba(255, 255, 255, .16);
    --muted: #c0c3ce;
    --glass-fill: linear-gradient(145deg, rgba(255,255,255,.04), rgba(255,255,255,.002) 46%, rgba(255,255,255,.018));
    --glass-shadow: inset 0 1px 0 rgba(255,255,255,.16), inset 0 -1px 0 rgba(255,255,255,.035), 0 8px 24px rgba(0,0,0,.12);
}
body { font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI", sans-serif; }
.wallpaper-shade { background: rgba(5, 6, 10, .07); }
.topbar { gap: 30px; }
.brand { letter-spacing: -.6px; }
.brand-mark { border-radius: 12px; box-shadow: inset 0 1px 1px #ffffff70, 0 3px 10px #0003; }
.topbar nav, .profile-button, .provider-tabs, .shortcut, .panel,
.search-field, .website-link, .saved-link, .button, .library-tile,
.setup-dialog, .toast, .gn-player-toolbar {
    background-color: var(--surface);
    background-image: var(--glass-fill);
    border: 1px solid var(--line);
    -webkit-backdrop-filter: blur(10px) saturate(135%);
    backdrop-filter: blur(10px) saturate(135%);
    box-shadow: var(--glass-shadow);
}
.topbar nav { gap: 4px; padding: 5px; border-radius: 25px; }
.nav-item { padding: 9px 16px; border-radius: 20px; color: #c4c6cf; font-size: 13px; }
.nav-item.active { background: rgba(255,255,255,.10); box-shadow: inset 0 1px 0 #ffffff1f, 0 2px 8px #0002; color: white; }
.nav-item.active:after { display: none; }
.nav-item:hover { background: rgba(255,255,255,.07); }
.nav-item.active:hover { background: rgba(255,255,255,.14); }
.header-tools { gap: 16px; }
.profile-button { padding: 5px 11px 5px 5px; border-radius: 25px; gap: 9px; }
.avatar { background: linear-gradient(145deg,#f3f4f9,#bbc2d0); box-shadow: inset 0 1px 1px #fff9; }
h1 { font-weight: 520; letter-spacing: -1.6px; }
.eyebrow { color: #c0c4d0; }
.library-tile { border-radius: 24px; color: #f7f8fa; background-color: rgba(28,36,26,.08); }
@supports (background: color-mix(in srgb, white, black)) {
    .library-tile { background-color: color-mix(in srgb, var(--accent) 4%, rgba(19,22,28,.10)); border-color: color-mix(in srgb, var(--accent) 22%, rgba(255,255,255,.19)); }
}
.library-tile .tile-symbol { color: var(--accent); text-shadow: 0 1px 0 #ffffff20; }
.library-tile strong { font-weight: 600; }
.library-tile small { opacity: 1; color: #c6ccd0; }
.tile-arrow { color: #dae2da; }
.library-tile:hover { background-color: rgba(66,77,58,.17); }
.featured-card, .gn-game-art { border-radius: 22px; border: 1px solid rgba(255,255,255,.24); box-shadow: inset 0 1px 1px #ffffff35, 0 10px 25px #0003; }
.featured-card:after { content: ''; position: absolute; inset: 0; border-radius: inherit; pointer-events: none; box-shadow: inset 0 1px 1px rgba(255,255,255,.32); background: linear-gradient(145deg,rgba(255,255,255,.10),transparent 36%); }
.featured-card .featured-caption { left: 8px; right: 8px; bottom: 8px; padding: 10px 12px; border: 1px solid #ffffff28; border-radius: 15px; background: rgba(18,20,26,.12); -webkit-backdrop-filter: blur(9px) saturate(145%) brightness(.52); backdrop-filter: blur(9px) saturate(145%) brightness(.52); box-shadow: inset 0 1px 0 #ffffff18, 0 3px 12px #0002; font-weight: 550; }
.shortcut, .panel { border-radius: 22px; }
.shortcut { transition: transform .2s, background-color .2s, border-color .2s; }
.shortcut:hover { background-color: rgba(55,58,67,.17); border-color: rgba(255,255,255,.3); transform: translateY(-2px); }
.shortcut-icon { opacity: .95; }
.shortcut small { color: #bec3cd; }
.shortcut-arrow { color: #bac0cc; }
.game-placeholder { border-radius: 22px; }
.provider-tabs { border-radius: 24px; }
.provider-tabs button { border-radius: 19px; }
.provider-tabs button[aria-selected=true] { background: rgba(255,255,255,.10); color: #fff; box-shadow: inset 0 1px 0 #ffffff2c, 0 2px 8px #0002; }
.search-field { border-radius: 19px; }
.search-field:focus-within { border-color: rgba(255,255,255,.45); box-shadow: var(--glass-shadow), 0 0 0 2px color-mix(in srgb,var(--accent) 32%,transparent); }
input, select { border-radius: 13px; background: rgba(9,12,18,.09); border-color: rgba(255,255,255,.16); box-shadow: inset 0 1px 3px #0003; }
.search-field input { background: transparent; box-shadow: none; border-radius: 0; }
select option { background: #20232b; color: white; }
.button { border-radius: 18px; padding: 11px 20px; background-color: rgba(69,73,85,.10); }
.button:hover { background-color: rgba(101,106,120,.20); }
.button.primary { background-color: rgba(122,160,85,.20); color: #fff; border-color: #ffffff38; background-image: linear-gradient(160deg,#ffffff22,#ffffff04); }
@supports (background: color-mix(in srgb, white, black)) {
    .button.primary { background-color: color-mix(in srgb,var(--accent) 14%,rgba(29,39,27,.14)); }
}
.button.primary:hover { filter: brightness(1.15); }
.button.quiet { background: transparent; border-color: transparent; box-shadow: none; -webkit-backdrop-filter: none; backdrop-filter: none; }
.website-link, .saved-link { border-radius: 16px; }
.website-link:hover, .saved-link:hover { border-color: rgba(255,255,255,.35); background-color: rgba(56,60,71,.17); }
.setup-dialog { background-color: rgba(22,24,31,.12); border-radius: 30px; box-shadow: inset 0 1px 1px #ffffff35, inset 1px 0 1px #ffffff0a, 0 35px 110px #0008; -webkit-backdrop-filter: blur(18px) saturate(140%) brightness(.8); backdrop-filter: blur(18px) saturate(140%) brightness(.8); }
.setup-dialog::backdrop { background: rgba(3,5,10,.08); -webkit-backdrop-filter: blur(2px); backdrop-filter: blur(2px); }
.setup-dialog h1 { font-weight: 550; }
.setup-dialog .brand-mark { border-radius: 12px; }
.accent-choice { box-shadow: inset 0 0 0 2px rgba(17,20,27,.7), inset 0 2px 3px #ffffff45, 0 2px 8px #0003; }
.wallpaper-choice { border-radius: 16px; background: rgba(67,73,87,.10); box-shadow: inset 0 1px 0 #ffffff15; }
.wallpaper-choice[aria-pressed=true] { border-color: rgba(255,255,255,.75); box-shadow: 0 0 0 2px color-mix(in srgb,var(--accent) 40%,transparent); }
.wallpaper-choice[aria-pressed=true] span { color: white; }
.gn-player-toolbar { border-radius: 0; background-color: rgba(22,24,31,.26); }
.gn-player-toolbar .button { border-radius: 14px; }
.toast { border-radius: 22px; background-color: rgba(36,40,51,.24); }
.gn-game-card:hover .gn-game-art { outline-color: rgba(255,255,255,.7); }
.dashboard-footer { color: #aeb5c2; }
@media(max-width:1050px) {
    .topbar { gap: 20px; }
    .topbar nav { gap: 2px; }
    .nav-item { padding: 9px 13px; }
    .profile-button { padding: 5px; }
}
@media(max-width:650px) {
    .topbar { row-gap: 17px; }
    .topbar nav { padding: 4px; gap: 1px; border-radius: 23px; }
    .nav-item { padding: 9px 10px; font-size: 11px; }
    .library-tile, .featured-card, .panel, .shortcut { border-radius: 20px; }
    .featured-card .featured-caption { left: 5px; right: 5px; bottom: 5px; padding: 7px!important; border-radius: 12px; font-size: 10px!important; }
    .gn-game-art { border-radius: 19px; }
    .setup-dialog { border-radius: 27px; }
    .wallpaper-choice { border-radius: 13px; }
    .profile-button { padding: 4px; }
}
@media(prefers-contrast:more) {
    :root { --surface: rgba(18,20,27,.94); --line: rgba(255,255,255,.4); --muted: #d5d9e3; }
    .setup-dialog, .featured-card .featured-caption { background-color: rgba(15,17,24,.95); }
}

/* Clear glass keeps the wallpaper legible through every large surface. */
.shortcut, .panel, .library-tile, .topbar nav, .setup-dialog { text-shadow: 0 1px 5px rgba(0,0,0,.45); }
.music-shortcut { display:grid; place-items:center; flex-shrink:0; width:38px; height:38px; padding:0; border-radius:50%; border:1px solid var(--line); color:#f2f5f8; background:var(--glass-fill),rgba(18,22,30,.10); box-shadow:var(--glass-shadow); -webkit-backdrop-filter:blur(10px) saturate(135%); backdrop-filter:blur(10px) saturate(135%); }
.music-shortcut:hover { background-color:rgba(255,255,255,.12); }
.music-shortcut[aria-pressed=false] { color:#aeb6c3; }
.music-volume-label { display:flex; align-items:center; justify-content:space-between; margin-top:18px; }
#music-volume { width:100%; height:22px; margin:10px 0 0; padding:0; accent-color:var(--accent); background:transparent; border:0; box-shadow:none; cursor:pointer; }
#music-status { margin:9px 0 0; }
@media(max-width:650px){.header-tools{gap:10px}.music-shortcut{width:34px;height:34px}}

/* One motion curve across glass controls; transform/opacity avoid layout jumps. */
:root { --motion-ease: cubic-bezier(.2,.75,.2,1); }
button, .button, .profile-button, .music-shortcut, .website-link, .saved-link,
.gn-game-art, .search-field, input, select {
    transition: transform 220ms var(--motion-ease), background-color 220ms var(--motion-ease),
        border-color 220ms var(--motion-ease), box-shadow 220ms var(--motion-ease),
        color 180ms ease, filter 220ms var(--motion-ease);
}
.library-tile, .featured-card, .shortcut { transition: transform 280ms var(--motion-ease), background-color 220ms var(--motion-ease), border-color 220ms var(--motion-ease), box-shadow 220ms var(--motion-ease); }
button:active:not(:disabled), .button:active:not(:disabled) { transform: scale(.97); transition-duration: 90ms; }
.library-tile:active, .featured-card:active, .shortcut:active { transform: translateY(0) scale(.982); }
.gn-game-card:active { transform: none; }
.gn-game-card:active .gn-game-art { transform: translateY(0) scale(.975); transition-duration: 100ms; }
.accent-choice { transition: transform 220ms var(--motion-ease), outline-color 180ms ease, box-shadow 220ms var(--motion-ease); }
.accent-choice[aria-pressed=true] { transform: scale(1.06); }
.accent-choice:active { transform: scale(.92); }
.wallpaper-choice { transition: transform 250ms var(--motion-ease), border-color 230ms var(--motion-ease), box-shadow 230ms var(--motion-ease); }
.wallpaper-choice span { transition: color 180ms ease; }
.wallpaper-choice:active { transform: scale(.98); }
.topbar nav, .provider-tabs { position: relative; isolation: isolate; }
.topbar nav:before, .provider-tabs:before {
    content: ''; position: absolute; top: 5px; bottom: 5px; left: 0;
    width: var(--indicator-width, 0px); transform: translateX(var(--indicator-x, 0px));
    border-radius: 20px; background: rgba(255,255,255,.10);
    box-shadow: inset 0 1px 0 #ffffff25, 0 2px 8px #0002;
    opacity: 0; pointer-events: none; z-index: -1;
    transition: transform 300ms var(--motion-ease), width 300ms var(--motion-ease), opacity 160ms ease;
}
.topbar nav.indicator-ready:before, .provider-tabs.indicator-ready:before { opacity: 1; }
.topbar nav.indicator-ready .nav-item.active,
.topbar nav.indicator-ready .nav-item.active:hover,
.provider-tabs.indicator-ready button[aria-selected=true] { background: transparent; box-shadow: none; }
.gn-game-card { animation: card-arrive 260ms var(--motion-ease) both; }
.gn-game-card:nth-child(2) { animation-delay: 12ms; }
.gn-game-card:nth-child(3) { animation-delay: 24ms; }
.gn-game-card:nth-child(4) { animation-delay: 36ms; }
.gn-game-card:nth-child(n+5) { animation-delay: 48ms; }
@keyframes card-arrive { from { opacity: 0; translate: 0 6px; } to { opacity: 1; translate: 0 0; } }
.setup-dialog[open]::backdrop { animation: backdrop-arrive 220ms ease-out both; }
@keyframes backdrop-arrive { from { opacity: 0; } to { opacity: 1; } }
@media (hover:hover) {
    .button:hover, .profile-button:hover, .music-shortcut:hover { transform: translateY(-1px); }
    .button:active, .profile-button:active, .music-shortcut:active { transform: translateY(0) scale(.97); }
}
@media(max-width:650px) { .topbar nav:before { top: 4px; bottom: 4px; } }
@media(prefers-reduced-motion:reduce) { *,*:before,*:after { transition:none!important; animation:none!important; } }
body.reduce-motion *, body.reduce-motion *:before, body.reduce-motion *:after { transition:none!important; animation:none!important; }

</style>
<script type="module">
// Same official SDK API used by the supplied Nocturne reference.
const LUMIN_SCRIPT = 'https://cdn.jsdelivr.net/gh/luminsdk/script@main/lumin.min.js';
let sdkPromise;
function deadline(promise, milliseconds, message) {
    let timer;
    return Promise.race([promise,new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error(message)),milliseconds);})]).finally(()=>clearTimeout(timer));
}
async function getLuminSdk() {
    if (!sdkPromise) sdkPromise=(async()=>{
        if(!window.Lumin){
            await deadline(new Promise((resolve,reject)=>{
                const script=document.createElement('script');script.src=LUMIN_SCRIPT;script.async=true;
                script.addEventListener('load',resolve,{once:true});script.addEventListener('error',()=>{script.remove();reject(new Error('The Lumin SDK could not be reached.'));},{once:true});document.head.append(script);
            }),20000,'The Lumin SDK timed out.');
        }
        if(!window.Lumin)throw new Error('The Lumin SDK did not start.');
        await deadline(window.Lumin.init({headless:true}),25000,'Lumin did not connect. Try again or use GN Math.');
        return window.Lumin;
    })().catch(error=>{sdkPromise=null;throw error;});
    return sdkPromise;
}
async function loadLuminCatalog() {
    const sdk=await getLuminSdk();let page=1,pages=1;const all=[];const ids=new Set();
    do {
        const result=await deadline(sdk.getGames({page,limit:100}),20000,'Lumin catalog request timed out.');
        const batch=Array.isArray(result)?result:result.games;
        if(!Array.isArray(batch))throw new Error('Lumin returned an invalid catalog.');
        let added=0;for(const game of batch){if(game.id==null||!game.name||ids.has(String(game.id)))continue;ids.add(String(game.id));all.push({id:game.id,name:game.name,imageToken:game.image_token,provider:'lumin'});added++;}
        pages=Number(result.pages)||1;page++;
        if(!added)break;
    }while(page<=pages&&page<=100);
    if(!all.length)throw new Error('Lumin returned an empty catalog.');
    return all;
}
async function loadLuminCover(token) {
    if(!token)return '';const sdk=await getLuminSdk();return deadline(sdk.getImageUrl(token),15000,'Cover unavailable.');
}
async function resolveLuminGame(id) {
    const sdk=await getLuminSdk();const result=await deadline(sdk.getGameUrl(id),25000,'Lumin could not resolve this game.');
    const url=typeof result==='string'?result:result?.url;
    if(!url||!/^https?:\/\//i.test(url))throw new Error('Lumin did not return a game URL.');return url;
}


// GN Math integration using the same catalog mirror and fetch-to-iframe approach
// as the supplied Opium reference. Lumin remains a separate selectable provider.
const SOURCES = [
    {
        catalog: 'https://cdn.jsdelivr.net/gh/freebuisness/assets@main/zones.json',
        html: 'https://cdn.jsdelivr.net/gh/freebuisness/html@main/',
        covers: 'https://cdn.jsdelivr.net/gh/freebuisness/covers@main/'
    },
    {
        catalog: 'https://raw.githubusercontent.com/gn-math/assets/main/zones.json',
        html: 'https://raw.githubusercontent.com/gn-math/html/main/',
        covers: 'https://raw.githubusercontent.com/gn-math/covers/main/'
    }
];
const PAGE_SIZE = 60;

async function fetchWithTimeout(url, options = {}) {
    const timeout = new AbortController();
    const abort = () => timeout.abort();
    if (options.signal?.aborted) abort();
    else options.signal?.addEventListener('abort', abort, { once: true });
    const timer = setTimeout(abort, 20000);
    try {
        const response = await fetch(url, { signal: timeout.signal });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        // Consume the body before clearing the timeout, including large games.
        return await response.text();
    } finally {
        clearTimeout(timer);
        options.signal?.removeEventListener('abort', abort);
    }
}

function gameDocument(html, url) {
    // Some catalog games use a Google Module / CDATA wrapper.
    const wrapped = html.match(/<Content[^>]*>\s*<!\[CDATA\[([\s\S]*?)\]\]>\s*<\/Content>/i);
    if (wrapped) html = wrapped[1];
    else if (/^\s*<Module\b/i.test(html)) {
        const start = html.search(/<!doctype html|<html\b/i);
        if (start >= 0) html = html.slice(start);
    }
    if (!/<(?:html|head|body|script|div|canvas|!doctype)\b/i.test(html)) {
        throw new Error('The game source did not contain an HTML document.');
    }
    if (/<base\b/i.test(html)) return html;
    const base = new URL('.', url).href.replace(/&/g, '&amp;').replace(/"/g, '&quot;');
    const element = `<base href="${base}">`;
    if (/<head\b[^>]*>/i.test(html)) return html.replace(/<head\b[^>]*>/i, head => head + element);
    if (/<html\b[^>]*>/i.test(html)) return html.replace(/<html\b[^>]*>/i, root => root + `<head>${element}</head>`);
    return element + html;
}

function initializeGnMath({ rebuildButtons, onOpen, onClose, playSound = () => {} }) {
    const grid = document.getElementById('g8mes-grid');
    const search = document.getElementById('g8me-search-input');
    const catalogStatus = document.getElementById('g8me-catalog-status');
    const catalogRetry = document.getElementById('g8me-retry-btn');
    const more = document.getElementById('g8me-load-more-btn');
    const player = document.getElementById('gn-game-player');
    const title = document.getElementById('gn-player-title');
    const host = document.getElementById('gn-frame-host');
    const message = document.getElementById('gn-player-message');
    const status = document.getElementById('gn-player-status');
    const retry = document.getElementById('gn-retry-btn');
    const close = document.getElementById('gn-close-btn');
    const fullscreen = document.getElementById('gn-fullscreen-btn');
    if (!grid || !player) return;

    let source = 'gn';
    let catalogGeneration = 0;
    const catalogs = new Map();
    let games = [];
    let matches = [];
    let shown = 0;
    let activeGame = null;
    let activeRequest = null;
    let generation = 0;
    let returnFocus = null;
    const sound = playSound;
    const exitFullscreenOnEscape = event => {
        if (event.key === 'Escape' && document.fullscreenElement === player) {
            event.preventDefault();
            document.exitFullscreen().catch(() => {});
        }
    };
    document.addEventListener('keydown', exitFullscreenOnEscape, true);

    function updateCount() {
        const query = search.value.trim();
        catalogStatus.textContent = `${matches.length.toLocaleString()}${query ? ' matching' : ''} ${source === 'lumin' ? 'Lumin' : 'GN Math'} games · ${shown.toLocaleString()} shown`;
        more.classList.toggle('hidden', shown >= matches.length);
        more.querySelector('.button-text').textContent = `Load more games (${Math.max(0, matches.length - shown).toLocaleString()} remaining)`;
    }

    function appendGames() {
        const end = Math.min(shown + PAGE_SIZE, matches.length);
        const fragment = document.createDocumentFragment();
        for (const game of matches.slice(shown, end)) {
            const card = document.createElement('button');
            card.type = 'button';
            card.className = 'gn-game-card';
            card.setAttribute('aria-label', `Play ${game.name}`);
            const art = document.createElement('span');
            art.className = 'gn-game-art';
            art.textContent = game.provider === 'lumin' ? 'L' : 'GN';
            art.setAttribute('aria-hidden', 'true');
            const image = document.createElement('img');
            if (game.provider !== 'lumin') image.src = game.cover;
            else if (game.imageToken) {
                const coverObserver = new IntersectionObserver(entries => {
                    if (!entries.some(entry => entry.isIntersecting)) return;
                    coverObserver.disconnect();
                    loadLuminCover(game.imageToken).then(url => { if (url && image.isConnected) image.src = url; }).catch(() => image.remove());
                }, { rootMargin: '180px' });
                coverObserver.observe(image);
            } else image.remove();
            image.alt = '';
            image.loading = 'lazy';
            image.decoding = 'async';
            let triedFallback = false;
            image.addEventListener('error', () => {
                if (!triedFallback && game.fallbackCover && game.fallbackCover !== game.cover) {
                    triedFallback = true;
                    image.src = game.fallbackCover;
                } else image.remove();
            });
            if (game.provider !== 'lumin' || game.imageToken) art.append(image);
            const label = document.createElement('span');
            label.className = 'gn-game-name';
            label.textContent = game.name;
            card.append(art, label);
            card.addEventListener('click', () => openGame(game, card));
            fragment.append(card);
        }
        shown = end;
        grid.append(fragment);
        updateCount();
        requestAnimationFrame(rebuildButtons);
    }

    function filterGames() {
        const query = search.value.trim().toLocaleLowerCase();
        matches = games.filter(game => game.name.toLocaleLowerCase().includes(query));
        shown = 0;
        grid.replaceChildren();
        grid.scrollTop = 0;
        appendGames();
        if (games.length && !matches.length) {
            const empty = document.createElement('p');
            empty.className = 'gn-empty';
            empty.textContent = 'No g8mes found.';
            grid.append(empty);
        }
    }

    async function fetchGnCatalog() {
        for (const endpoint of SOURCES) {
            try {
                const data = JSON.parse(await fetchWithTimeout(endpoint.catalog));
                if (!Array.isArray(data)) throw new Error('Invalid catalog');
                const playable = data.filter(game => Number(game.id) >= 0 && typeof game.name === 'string' &&
                    !game.name.startsWith('[!]') && typeof game.url === 'string' && game.url.startsWith('{HTML_URL}/'));
                if (!playable.length) throw new Error('Empty catalog');
                return playable.map(game => {
                    const path = game.url.slice('{HTML_URL}/'.length);
                    const coverPath = typeof game.cover === 'string' && game.cover.startsWith('{COVER_URL}/') ? game.cover.slice('{COVER_URL}/'.length) : `${game.id}.png`;
                    return {
                        id: game.id, name: game.name, provider: 'gn',
                        urls: [...new Set([new URL(path, endpoint.html).href,
                            `https://raw.githubusercontent.com/freebuisness/html/main/${path}`,
                            `https://raw.githubusercontent.com/gn-math/html/main/${path}`])],
                        cover: new URL(coverPath, endpoint.covers).href,
                        fallbackCover: `https://raw.githubusercontent.com/gn-math/covers/main/${coverPath}`
                    };
                });
            } catch (error) { console.warn('GN Math source unavailable:', error.message); }
        }
        throw new Error('Could not reach GN Math. Check your connection and try again.');
    }
    async function loadCatalog() {
        const version = ++catalogGeneration;
        const requestedSource = source;
        catalogRetry.classList.add('hidden'); more.classList.add('hidden');
        grid.setAttribute('aria-busy', 'true'); grid.replaceChildren();
        games = []; matches = [];
        catalogStatus.textContent = `Loading ${source === 'lumin' ? 'Lumin' : 'GN Math'}...`;
        try {
            const catalog = catalogs.get(requestedSource) || await (requestedSource === 'lumin' ? loadLuminCatalog() : fetchGnCatalog());
            catalogs.set(requestedSource, catalog);
            document.dispatchEvent(new CustomEvent('catalogready', { detail: { source: requestedSource, games: catalog } }));
            if (version !== catalogGeneration) return;
            games = [...catalog].sort((a,b) => a.name.localeCompare(b.name, undefined, {sensitivity:'base',numeric:true}));
            grid.setAttribute('aria-busy','false'); filterGames();
        } catch (error) {
            if (version !== catalogGeneration) return;
            grid.setAttribute('aria-busy','false');
            catalogStatus.textContent = source === 'lumin' ? `Lumin is unavailable: ${error.message} GN Math is still available.` : error.message;
            catalogRetry.classList.remove('hidden');
        }
    }
    async function setSource(next) {
        source = next === 'lumin' ? 'lumin' : 'gn';
        search.value = '';
        document.querySelectorAll('[data-source]').forEach(button => { const selected = button.dataset.source === source; button.setAttribute('aria-selected', String(selected)); button.tabIndex = selected ? 0 : -1; });
        await loadCatalog();
    }

    async function openGame(game, trigger = null) {
        sound();
        const wasClosed = player.classList.contains('hidden');
        if (trigger) returnFocus = trigger;
        activeRequest?.abort();
        const request = new AbortController();
        activeRequest = request;
        const current = ++generation;
        activeGame = game;
        host.replaceChildren();
        title.textContent = game.name;
        player.classList.remove('hidden');
        document.querySelectorAll('.topbar, main, .dashboard-footer').forEach(element => { element.inert = true; });
        message.classList.remove('hidden');
        retry.classList.add('hidden');
        status.textContent = `Loading ${game.name}...`;
        if (wasClosed) onOpen();
        close.focus();
        requestAnimationFrame(rebuildButtons);
        const mountFrame = (value, isDocument) => {
            if (current !== generation || request.signal.aborted) return;
            const frame = document.createElement('iframe');
            frame.id = 'gn-game-frame'; frame.title = game.name;
            frame.allow = 'autoplay; fullscreen; gamepad; clipboard-write'; frame.allowFullscreen = true;
            frame.addEventListener('load', () => {
                if (current !== generation) return;
                message.classList.add('hidden');
                frame.contentDocument?.addEventListener('keydown', exitFullscreenOnEscape, true);
                frame.contentWindow?.focus();
                document.dispatchEvent(new CustomEvent('gameplayed', {detail:game}));
            }, {once:true});
            if (isDocument) frame.srcdoc = value; else frame.src = value;
            host.replaceChildren(frame);
        };
        if (game.provider === 'lumin') {
            try { const url = await resolveLuminGame(game.id); mountFrame(url,false); return; }
            catch (error) {
                if (current !== generation) return;
                status.textContent = `Could not start ${game.name}: ${error.message}`;
                retry.classList.remove('hidden'); return;
            }
        }
        for (const url of game.urls) {
            try {
                const html = gameDocument(await fetchWithTimeout(url, {signal:request.signal}),url);
                mountFrame(html,true); return;
            } catch (error) {
                if (current !== generation || request.signal.aborted) return;
                console.warn('Game source unavailable:',url,error.message);
            }
        }
        if (current !== generation) return;
        status.textContent = `Could not load ${game.name}. Try again or choose another game.`;
        retry.classList.remove('hidden');
        requestAnimationFrame(rebuildButtons);
    }

    async function closeGame() {
        sound();
        ++generation;
        activeRequest?.abort();
        activeGame = null;
        // Removing the iframe stops its scripts, audio, timers, and network activity.
        host.replaceChildren();
        if (document.fullscreenElement === player) await document.exitFullscreen().catch(() => {});
        player.classList.add('hidden');
        document.querySelectorAll('.topbar, main, .dashboard-footer').forEach(element => { element.inert = false; });
        onClose();
        returnFocus?.focus({ preventScroll: true });
    }

    search.addEventListener('input', filterGames);
    more.addEventListener('click', () => { sound(); appendGames(); });
    catalogRetry.addEventListener('click', loadCatalog);
    retry.addEventListener('click', () => { if (activeGame) openGame(activeGame); });
    document.getElementById('gn-reload-btn').addEventListener('click', () => { if (activeGame) openGame(activeGame); });
    close.addEventListener('click', closeGame);
    fullscreen.disabled = !player.requestFullscreen;
    fullscreen.addEventListener('click', async () => {
        sound();
        try {
            if (document.fullscreenElement === player) await document.exitFullscreen();
            else await player.requestFullscreen();
        } catch (error) { console.warn('Fullscreen unavailable:', error.message); }
    });
    document.addEventListener('fullscreenchange', () => {
        fullscreen.querySelector('.button-text').textContent = document.fullscreenElement === player ? 'Exit Fullscreen' : 'Fullscreen';
    });
    loadCatalog();
    return { launch: openGame, setSource, getGames: () => games };
}


const $ = id => document.getElementById(id);
const read = (key, fallback = null) => { try { return JSON.parse(localStorage.getItem(key)) ?? fallback; } catch { return fallback; } };
const write = (key, value) => { try { localStorage.setItem(key, JSON.stringify(value)); } catch { toast('Your browser could not save this preference.'); } };
const WALLPAPERS = [
    { id: 'windows', name: 'Windows 11', url: 'data:image/jpeg;base64,' },
    { id: 'playstation', name: 'PlayStation', url: 'data:image/jpeg;base64,' },
    { id: 'macos', name: 'macOS', url: 'data:image/jpeg;base64,' }
];
const ACCENTS = [['#8edb44','Xbox green'],['#72b6ff','Sky blue'],['#b4a0ff','Violet'],['#ffb86c','Amber'],['#ff8eb5','Rose'],['#e6eaf0','Silver']];
const DEFAULT_PROFILE = { name: 'Player', wallpaper: 'windows', accent: '#8edb44' };
let profile = read('gbProfileV1');
if (!profile || !WALLPAPERS.some(x => x.id === profile.wallpaper) || !ACCENTS.some(x => x[0] === profile.accent)) profile = null;
let draft = { ...(profile || DEFAULT_PROFILE) };
let route = 'home';
let currentSource = 'gn';
let library;
let featured = [];
let lastGame = null;
let linksPromise;
let builtin = [];
let linkMatches = [];
let linksShown = 0;
const defaultIcon = $('favicon-link').href;
let toastTimer;
function toast(message) { $('toast').textContent = message; $('toast').classList.remove('hidden'); clearTimeout(toastTimer); toastTimer = setTimeout(() => $('toast').classList.add('hidden'), 3800); }
const menuMusic = new Audio('data:audio/mpeg;base64,');
menuMusic.loop = true;
menuMusic.preload = 'none';
const selectSound = new Audio('data:audio/mpeg;base64,');
selectSound.preload = 'auto';
selectSound.volume = .4;
let audioUnlocked = false;
let gameIsOpen = false;
let musicEnabled = read('gbMusicEnabled', true);
let musicVolume = Math.min(1, Math.max(0, Number(read('gbMusicVolume', .18)) || 0));
let musicContext;
let musicGain;
let musicSource;
let lastSelectTime = -Infinity;
function updateMusicControls() {
    $('music-toggle').checked = musicEnabled;
    $('music-shortcut').setAttribute('aria-pressed', String(musicEnabled));
    const action = musicEnabled ? 'Turn background music off' : 'Turn background music on';
    $('music-shortcut').setAttribute('aria-label', action);
    $('music-shortcut').title = action;
    $('music-waves').classList.toggle('hidden', !musicEnabled);
    $('music-muted').classList.toggle('hidden', musicEnabled);
    $('music-volume').value = String(Math.round(musicVolume * 100));
    $('music-volume-value').textContent = `${Math.round(musicVolume * 100)}%`;
    if (!musicEnabled) $('music-status').textContent = 'Background music is off.';
    else if (gameIsOpen) $('music-status').textContent = 'Music is paused while a game is open.';
    else if (!audioUnlocked) $('music-status').textContent = 'Music starts after your first click or tap.';
    else if (!menuMusic.paused) $('music-status').textContent = 'Playing softly in the background.';
    else $('music-status').textContent = 'Music is ready to play.';
}
function prepareMusicOutput() {
    // A gain node also controls volume on mobile browsers that ignore audio.volume.
    if (!musicContext) {
        const AudioContextType = window.AudioContext || window.webkitAudioContext;
        if (AudioContextType) {
            musicContext = new AudioContextType();
            musicSource = musicContext.createMediaElementSource(menuMusic);
            musicGain = musicContext.createGain();
            musicSource.connect(musicGain).connect(musicContext.destination);
        }
    }
    if (musicGain) { menuMusic.volume = 1; musicGain.gain.setValueAtTime(musicVolume, musicContext.currentTime); }
    else menuMusic.volume = musicVolume;
    musicContext?.resume().catch(() => {});
}
function syncMusic() {
    if (!musicEnabled || gameIsOpen || !audioUnlocked) { menuMusic.pause(); updateMusicControls(); return; }
    try { prepareMusicOutput(); } catch { menuMusic.volume = musicVolume; }
    if (!menuMusic.paused) { updateMusicControls(); return; }
    menuMusic.play().then(updateMusicControls).catch(error => {
        if (error.name === 'AbortError') return;
        updateMusicControls();
        if (musicEnabled && !gameIsOpen) $('music-status').textContent = 'Tap the speaker button to start the music.';
    });
}
function setMusicEnabled(enabled) {
    musicEnabled = enabled; write('gbMusicEnabled', enabled); syncMusic();
}
function sound() {
    if (!read('gbSounds', true)) return;
    const now = performance.now(); if (now - lastSelectTime < 75) return;
    lastSelectTime = now;
    selectSound.currentTime = 0;
    selectSound.play().catch(() => {});
}
function unlockAudio() {
    if (audioUnlocked) return;
    audioUnlocked = true;
    syncMusic();
}
document.addEventListener('click', event => {
    if (!event.isTrusted) return;
    unlockAudio();
    if (event.target.closest('button, a, input[type="checkbox"]')) sound();
}, true);
document.addEventListener('keydown', event => {
    if (['Tab', 'Enter', ' '].includes(event.key)) unlockAudio();
}, true);
$('music-shortcut').addEventListener('click', () => setMusicEnabled(!musicEnabled));
$('music-toggle').addEventListener('change', event => setMusicEnabled(event.target.checked));
$('music-volume').addEventListener('input', event => {
    musicVolume = Number(event.target.value) / 100;
    write('gbMusicVolume', musicVolume);
    syncMusic();
});
menuMusic.addEventListener('playing', updateMusicControls);
menuMusic.addEventListener('pause', updateMusicControls);
menuMusic.addEventListener('error', () => { $('music-status').textContent = 'The music could not be loaded. Try refreshing the page.'; });
updateMusicControls();
// Cancel an interrupted animation before starting the next interaction.
const activeMotions = new Map();
const reducedMotion = () => document.body.classList.contains('reduce-motion') || window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function animateElement(element, frames, options = {}) {
    if (!element) return Promise.resolve();
    activeMotions.get(element)?.cancel();
    if (reducedMotion() || !element.animate) return Promise.resolve();
    const animation = element.animate(frames, { duration: 240, easing: 'cubic-bezier(.2,.75,.2,1)', ...options });
    activeMotions.set(element, animation);
    return animation.finished.catch(() => {}).finally(() => {
        if (activeMotions.get(element) === animation) activeMotions.delete(element);
        animation.cancel();
    });
}
function reveal(element) {
    return animateElement(element, [{ opacity: 0, transform: 'translateY(8px)' }, { opacity: 1, transform: 'translateY(0)' }]);
}
function updateIndicators() {
    for (const [container, selected] of [
        [document.querySelector('.topbar nav'), document.querySelector('.nav-item.active')],
        [document.querySelector('.provider-tabs'), document.querySelector('[data-source][aria-selected="true"]')]
    ]) {
        if (!container) continue;
        if (!selected) { container.classList.remove('indicator-ready'); continue; }
        if (!selected.offsetWidth) continue;
        container.style.setProperty('--indicator-x', `${selected.offsetLeft}px`);
        container.style.setProperty('--indicator-width', `${selected.offsetWidth}px`);
        container.classList.add('indicator-ready');
    }
}
window.addEventListener('resize', () => requestAnimationFrame(updateIndicators));
new MutationObserver(updateIndicators).observe(document.querySelector('.provider-tabs'), { subtree: true, attributes: true, attributeFilter: ['aria-selected'] });
let setupClosing = false;
async function closePersonalize() {
    if (setupClosing) return;
    const dialog = $('personalize-dialog');
    setupClosing = true;
    try {
        await animateElement(dialog, [{ opacity: 1, transform: 'translateY(0) scale(1)' }, { opacity: 0, transform: 'translateY(5px) scale(.985)' }], { duration: 140, easing: 'cubic-bezier(.4,0,1,1)', fill: 'forwards' });
        dialog.close();
    } finally { setupClosing = false; }
}
function updateChoices() {
    document.querySelectorAll('.accent-choice').forEach(button => button.setAttribute('aria-pressed', String(button.dataset.accent === draft.accent)));
    document.querySelectorAll('.wallpaper-choice').forEach(button => button.setAttribute('aria-pressed', String(button.dataset.wallpaper === draft.wallpaper)));
}
function applyProfile(value) {
    const wallpaper = WALLPAPERS.find(x => x.id === value.wallpaper) || WALLPAPERS[0];
    document.documentElement.style.setProperty('--wallpaper', `url("${wallpaper.url}")`);
    document.documentElement.style.setProperty('--accent', value.accent);
    $('welcome-name').textContent = value.name || 'Player';
    $('profile-name').textContent = value.name || 'Player';
    $('profile-avatar').textContent = (value.name || 'P').slice(0, 1).toUpperCase();
}
function renderChoices() {
    $('accent-choices').replaceChildren(...ACCENTS.map(([color,name]) => {
        const button = document.createElement('button'); button.type = 'button'; button.className = 'accent-choice';
        button.dataset.accent = color; button.style.setProperty('--choice', color); button.setAttribute('aria-label', name); button.setAttribute('aria-pressed', String(draft.accent === color));
        button.addEventListener('click', () => { draft.accent = color; applyProfile(draft); updateChoices(); }); return button;
    }));
    $('wallpaper-choices').replaceChildren(...WALLPAPERS.map(wallpaper => {
        const button = document.createElement('button'); button.type = 'button'; button.className = 'wallpaper-choice';
        button.dataset.wallpaper = wallpaper.id; button.setAttribute('aria-label', `${wallpaper.name} wallpaper`); button.setAttribute('aria-pressed', String(draft.wallpaper === wallpaper.id));
        const image = document.createElement('img'); image.src = wallpaper.url; image.alt = '';
        const label = document.createElement('span'); label.textContent = wallpaper.name; button.append(image,label);
        button.addEventListener('click', () => { draft.wallpaper = wallpaper.id; applyProfile(draft); updateChoices(); }); return button;
    }));
}
function personalize() {
    if (setupClosing || $('personalize-dialog').open) return;
    draft = { ...(profile || DEFAULT_PROFILE) };
    $('display-name-input').value = profile?.name || '';
    $('setup-title').textContent = profile ? 'Your dashboard. Your rules.' : 'Make yourself at home.';
    $('setup-eyebrow').textContent = profile ? 'PERSONALIZE YOUR SPACE' : 'WELCOME TO YOUR BUNKER';
    $('setup-cancel').textContent = profile ? 'Cancel' : 'Use defaults';
    $('setup-save').firstChild.textContent = profile ? 'Save changes ' : "Let's play ";
    renderChoices(); $('personalize-dialog').showModal();
    animateElement($('personalize-dialog'), [{opacity:0,transform:'translateY(10px) scale(.975)'},{opacity:1,transform:'translateY(0) scale(1)'}], {duration:260});
}
$('personalize-form').addEventListener('submit', event => {
    event.preventDefault(); if (setupClosing) return; draft.name = $('display-name-input').value.trim() || 'Player';
    profile = { ...draft }; write('gbProfileV1', profile); applyProfile(profile); closePersonalize(); sound();
});
$('setup-cancel').addEventListener('click', () => {
    if (setupClosing) return;
    if (!profile) { profile = { ...DEFAULT_PROFILE }; write('gbProfileV1', profile); }
    applyProfile(profile); closePersonalize();
});
$('personalize-dialog').addEventListener('cancel', event => {
    event.preventDefault();
    if (profile) { applyProfile(profile); closePersonalize(); }
});
$('display-name-input').addEventListener('input', () => { draft.name = $('display-name-input').value.trim() || 'Player'; applyProfile(draft); });
for (const id of ['profile-btn','home-personalize','settings-personalize']) $(id).addEventListener('click', personalize);
function showView(name) {
    if (!['home','games','links','settings','credits'].includes(name)) name = 'home';
    const changed = route !== name;
    route = name;
    document.querySelectorAll('main>.page').forEach(page => page.classList.toggle('hidden', page.id !== `view-${name}`));
    document.querySelectorAll('.nav-item').forEach(button => {
        const active = button.dataset.view === name; button.classList.toggle('active', active);
        if (active) button.setAttribute('aria-current','page'); else button.removeAttribute('aria-current');
    });
    updateIndicators();
    if (changed) reveal($(`view-${name}`));
    try { window.parent.location.hash = name; } catch {}
    if (name === 'links') loadWebsites();
    window.scrollTo({top:0,behavior:'instant'});
}
document.addEventListener('click', event => {
    const nav = event.target.closest('[data-view]');
    if (nav) { event.preventDefault(); sound(); showView(nav.dataset.view); }
});
function updateClock() { $('dashboard-clock').textContent = new Intl.DateTimeFormat(undefined,{hour:'numeric',minute:'2-digit'}).format(new Date()); }
updateClock(); setInterval(updateClock,30000);
$('sound-toggle').checked = read('gbSounds',true);
$('sound-toggle').addEventListener('change', event => { write('gbSounds',event.target.checked); sound(); });
$('motion-toggle').checked = read('gbReduceMotion',false);
document.body.classList.toggle('reduce-motion',$('motion-toggle').checked);
$('motion-toggle').addEventListener('change',event => { write('gbReduceMotion',event.target.checked); document.body.classList.toggle('reduce-motion',event.target.checked); if (event.target.checked) for (const motion of activeMotions.values()) motion.cancel(); });
try { $('tab-title-input').value = localStorage.getItem('customTabTitle') || ''; $('tab-icon-select').value = localStorage.getItem('customTabIcon') || ''; } catch {}
function applyTab() { document.title = $('tab-title-input').value.trim() || 'Geeks Bunker'; $('favicon-link').href = $('tab-icon-select').value || defaultIcon; }
applyTab();
$('tab-settings-form').addEventListener('submit',event => {
    event.preventDefault(); applyTab();
    try { localStorage.setItem('customTabTitle',$('tab-title-input').value.trim()); localStorage.setItem('customTabIcon',$('tab-icon-select').value); } catch {}
    $('tab-status').textContent = 'Tab settings saved.';
});
$('about-blank-btn').addEventListener('click', () => {
    const win = window.open('about:blank','_blank'); if (!win) return toast('Allow pop-ups to open a blank tab.');
    win.document.title = document.title;
    Object.assign(win.document.body.style,{margin:'0',height:'100vh',background:'#101318'});
    const frame = win.document.createElement('iframe'); frame.src = document.baseURI;
    Object.assign(frame.style,{width:'100%',height:'100%',border:'0'}); frame.allow = 'fullscreen; autoplay; gamepad; clipboard-write'; frame.allowFullscreen = true;
    win.document.body.append(frame);
    window.parent.location.replace('https://www.google.com');
});
function renderSaved() {
    const saved = read('userSavedLinks',[]);
    $('user-links-grid').replaceChildren();
    if (!Array.isArray(saved) || !saved.length) { const p = document.createElement('p'); p.className='muted'; p.textContent='Keep your favorites close. Save a website to get started.'; $('user-links-grid').append(p); return; }
    saved.forEach((item,index) => {
        const row=document.createElement('div'); row.className='saved-link';
        const link=document.createElement('a'); link.textContent=item.name; link.href=item.url; link.target='_blank'; link.rel='noopener noreferrer';
        const remove=document.createElement('button'); remove.className='delete-link'; remove.textContent='×'; remove.setAttribute('aria-label',`Delete ${item.name}`);
        remove.addEventListener('click',()=>{ saved.splice(index,1); write('userSavedLinks',saved); renderSaved(); }); row.append(link,remove); $('user-links-grid').append(row);
    });
}
$('save-link-form').addEventListener('submit',event => {
    event.preventDefault();
    try {
        let url=$('custom-link-url').value.trim(); if (!/^https?:\/\//i.test(url)) url='https://'+url;
        const parsed=new URL(url); if (!['http:','https:'].includes(parsed.protocol)) throw new Error();
        const saved=read('userSavedLinks',[]); saved.push({name:$('custom-link-name').value.trim(),url:parsed.href}); write('userSavedLinks',saved);
        $('save-link-form').reset(); $('link-feedback').textContent='Website saved.'; renderSaved();
    } catch { $('link-feedback').textContent='Enter a valid website URL.'; }
});
async function getLinks() {
    if (!linksPromise) linksPromise=(async()=>{
        const embedded=$('embedded-links');
        if (embedded) {
            const bytes=Uint8Array.from(atob(embedded.textContent.trim()),char=>char.charCodeAt(0));
            return JSON.parse(await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text());
        }
        return (await import('./links.js')).links;
    })().catch(error=>{linksPromise=null;throw error;});
    return linksPromise;
}
function appendWebsites() {
    const fragment=document.createDocumentFragment(); const batch=linkMatches.slice(linksShown,linksShown+100);
    for(const item of batch) { const button=document.createElement('button'); button.className='website-link'; button.textContent=item.name||'Website'; button.addEventListener('click',()=>window.open(typeof item==='string'?item:item.url,'_blank','noopener,noreferrer')); fragment.append(button); }
    linksShown+=batch.length; $('built-in-links-grid').append(fragment); $('website-more').classList.toggle('hidden',linksShown>=linkMatches.length);
    $('builtin-count').textContent=`${linkMatches.length.toLocaleString()} websites · ${linksShown.toLocaleString()} shown`;
}
function filterWebsites() { const query=$('website-search').value.trim().toLowerCase(); linkMatches=builtin.filter(x=>`${x.name} ${x.url}`.toLowerCase().includes(query)); linksShown=0; $('built-in-links-grid').replaceChildren(); appendWebsites(); }
async function loadWebsites() {
    renderSaved(); $('builtin-count').textContent='Loading collection...';
    try { builtin=await getLinks(); filterWebsites(); } catch { $('builtin-count').textContent='Collection unavailable. Select Websites to retry.'; }
}
$('website-search').addEventListener('input',filterWebsites); $('website-more').addEventListener('click',appendWebsites);
$('feeling-lucky-btn').addEventListener('click',async()=>{
    const win=window.open('about:blank','_blank'); if(!win)return toast('Allow pop-ups to open a random website.');
    try { const all=await getLinks(); const item=all[Math.floor(Math.random()*all.length)]; win.opener=null; win.location.href=typeof item==='string'?item:item.url; } catch { win.close();toast('Could not load the website collection.'); }
});
function renderFeatured(games) {
    const picks=[1,6,114,82].map(id=>games.find(g=>g.id===id)).filter(Boolean); featured=picks.length===4?picks:games.slice(0,4);
    $('featured-games').replaceChildren(...featured.map(game=>{
        const card=document.createElement('button'); card.className='featured-card'; card.setAttribute('aria-label',`Play ${game.name}`);
        const image=document.createElement('img'); image.src=game.cover; image.alt=''; image.addEventListener('error',()=>image.remove(),{once:true});
        const label=document.createElement('span'); label.className='featured-caption';label.textContent=game.name;
        card.append(image,label); card.addEventListener('click',()=>library.launch(game,card)); return card;
    }));
}
document.addEventListener('catalogready',event=>{ if(event.detail.source==='gn') renderFeatured(event.detail.games); });
document.addEventListener('gameplayed',event=>{ lastGame=event.detail; write('gbRecentGame',{name:lastGame.name,source:lastGame.provider||'gn',id:lastGame.id}); updateRecent(); });
function updateRecent() { const recent=read('gbRecentGame'); if(recent){$('recent-title').textContent=recent.name;$('recent-description').textContent=`Continue from ${recent.source==='lumin'?'Lumin':'GN Math'}`;} }
$('recent-game').addEventListener('click',async()=>{
    if(lastGame)return library.launch(lastGame,$('recent-game'));
    const recent=read('gbRecentGame'); if(recent){showView('games');await library.setSource(recent.source);const game=library.getGames().find(x=>String(x.id)===String(recent.id));if(game)return library.launch(game,$('recent-game'));} else showView('games');
});
for(const button of document.querySelectorAll('[data-source]'))button.addEventListener('click',()=>{sound();currentSource=button.dataset.source;library.setSource(currentSource);});
document.querySelectorAll('[data-source]').forEach(button=>button.addEventListener('keydown',event=>{
    if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;
    event.preventDefault();const next=event.key==='Home'?'gn':event.key==='End'?'lumin':button.dataset.source==='gn'?'lumin':'gn';
    library.setSource(next);document.querySelector(`[data-source="${next}"]`).focus();
}));
library=initializeGnMath({
    rebuildButtons:()=>{},
    onOpen:()=>{ gameIsOpen=true; syncMusic(); reveal($('gn-game-player')); },
    onClose:()=>{ gameIsOpen=false; syncMusic(); reveal($(`view-${route}`)); },
    playSound:sound
});
applyProfile(profile||DEFAULT_PROFILE);updateRecent();
let initial='home';try{initial=window.parent.location.hash.slice(1)||'home';}catch{}showView(initial);
if(!profile)personalize();

</script>
</head>
<body><script id="embedded-links" type="application/octet-stream"></script>
<div class="wallpaper" aria-hidden="true"></div><div class="wallpaper-shade" aria-hidden="true"></div>
<header class="topbar">
 <a class="brand" href="#home" data-view="home" aria-label="Geeks Bunker Home"><span class="brand-mark">G<span>•</span></span><span>geeks bunker</span></a>
 <nav aria-label="Main navigation">
  <button data-view="home" class="nav-item active" aria-current="page">Home</button>
  <button data-view="games" class="nav-item">Game library</button>
  <button data-view="links" class="nav-item">Websites</button>
  <button data-view="settings" class="nav-item">Settings</button>
 </nav>
 <div class="header-tools"><time id="dashboard-clock"></time><button id="music-shortcut" class="music-shortcut" aria-label="Turn background music off" aria-pressed="true" title="Turn background music off"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4Z"/><path id="music-waves" d="M15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/><path id="music-muted" class="hidden" d="m16 9 5 6m0-6-5 6"/></svg></button><button id="profile-btn" class="profile-button" aria-label="Customize your profile"><span class="avatar" id="profile-avatar">P</span><span id="profile-name">Player</span></button></div>
</header>
<main>
 <section id="view-home" class="page home-page">
  <div class="welcome"><p class="eyebrow">YOUR SPACE. YOUR GAMES.</p><h1>Welcome back, <span id="welcome-name">Player</span>.</h1><p>Something good to play. A place that feels like you.</p></div>
  <div class="section-heading"><h2>Jump into a game</h2><button class="text-button" data-view="games">View all games <span aria-hidden="true">→</span></button></div>
  <div class="home-strip" id="home-games">
   <button class="library-tile" data-view="games"><span class="tile-symbol" aria-hidden="true">▦</span><span><strong>Your game library</strong><small>GN Math + Lumin</small></span><span class="tile-arrow" aria-hidden="true">↗</span></button>
   <div id="featured-games" class="featured-games"><div class="game-placeholder">Loading your next favorite...</div></div>
  </div>
  <div class="section-heading shortcuts-heading"><h2>Make yourself at home</h2><span class="muted">Everything, one click away.</span></div>
  <div class="shortcut-grid">
   <button class="shortcut" data-view="links"><span class="shortcut-icon" aria-hidden="true">↗</span><span><strong>Your websites</strong><small>Saved links & the full built-in collection</small></span><span class="shortcut-arrow" aria-hidden="true">→</span></button>
   <button class="shortcut" id="home-personalize"><span class="shortcut-icon" aria-hidden="true">◐</span><span><strong>Make it yours</strong><small>Wallpapers, colors & your profile</small></span><span class="shortcut-arrow" aria-hidden="true">→</span></button>
   <button class="shortcut recent-shortcut" id="recent-game"><span class="shortcut-icon" aria-hidden="true">▷</span><span><strong id="recent-title">Ready when you are</strong><small id="recent-description">Your last game will appear here</small></span><span class="shortcut-arrow" aria-hidden="true">→</span></button>
  </div>
 </section>
 <section id="view-games" class="page hidden">
  <div class="page-heading"><div><p class="eyebrow">ALL YOUR FAVORITES</p><h1>Game library</h1></div><div class="provider-tabs" role="tablist" aria-label="Game source"><button id="provider-gn" role="tab" aria-selected="true" data-source="gn">GN Math</button><button id="provider-lumin" role="tab" tabindex="-1" aria-selected="false" data-source="lumin">Lumin</button></div></div>
  <div class="library-controls"><label class="search-field"><span aria-hidden="true">⌕</span><input id="g8me-search-input" type="search" placeholder="Search your next game" aria-label="Search games" autocomplete="off"></label><p id="g8me-catalog-status" role="status">Loading GN Math...</p></div>
  <button id="g8me-retry-btn" class="button hidden" type="button">Try again</button>
  <div id="g8mes-grid" class="game-grid" aria-label="Games" aria-busy="true"></div>
  <button id="g8me-load-more-btn" class="button more-button hidden" type="button"><span class="button-text">Load more</span></button>
 </section>
 <section id="view-links" class="page hidden">
  <div class="page-heading"><div><p class="eyebrow">YOUR CORNER OF THE WEB</p><h1>Websites</h1></div><button class="button" id="feeling-lucky-btn">Feeling lucky ↗</button></div>
